package com.smarthub.plus;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.view.accessibility.*;import org.json.*;import java.util.*;
final class ManufacturerAcceptance35 {
 static void run(Instrumentation test,Context c,Bundle args,Bundle out)throws Exception{List<ManufacturerFeatures.Entry> entries=ManufacturerFeatures.read(c);JSONArray inventory=new JSONArray();int count=0;for(ManufacturerFeatures.Entry e:entries){String blocked=ManufacturerFeatures.unavailable(c,e);if(blocked.isEmpty())count++;inventory.put(new JSONObject().put("id",e.id).put("title",e.title).put("action",e.intent.getAction()).put("available",blocked.isEmpty()).put("reason",blocked));}out.putInt("oem_feature_count",entries.size());out.putInt("oem_features_available",count);out.putString("oem_features",inventory.toString());if(entries.isEmpty()||count==0)throw new AssertionError("Original menu resources or public activities unavailable");Bundle filtered=ManufacturerFeatures.parseBundle("host_type:Other_Module,sub_host_type:1002,password:excluded,token:excluded,from_home:true");if(filtered.containsKey("password")||filtered.containsKey("token")||filtered.getInt("sub_host_type")!=1002)throw new AssertionError("Navigation extras not restricted");out.putBoolean("oem_extras_allowlist",true);
 String id=args.getString("open","");if(id.isEmpty())return;if(!Arrays.asList("server","ca","patch","homeshare").contains(id))throw new AssertionError("This diagnostic only opens non-tuning OEM screens");ManufacturerFeatures.Entry target=ManufacturerFeatures.find(c,id);if(target==null||!ManufacturerFeatures.unavailable(c,target).isEmpty())throw new AssertionError("OEM feature unavailable");Activity owner=test.startActivitySync(new Intent(c,ManufacturerToolsActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));boolean[] opened={false};test.runOnMainSync(()->opened[0]=ManufacturerFeatures.open(owner,target));out.putBoolean("oem_launch_from_normal_uid",opened[0]);if(!opened[0])throw new AssertionError("Normal app could not open original feature");java.util.concurrent.atomic.AtomicReference<Activity> resumed=new java.util.concurrent.atomic.AtomicReference<>();Application app=(Application)c.getApplicationContext();Application.ActivityLifecycleCallbacks callbacks=new Application.ActivityLifecycleCallbacks(){public void onActivityResumed(Activity a){resumed.set(a);}public void onActivityCreated(Activity a,Bundle b){}public void onActivityStarted(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}};test.runOnMainSync(()->app.registerActivityLifecycleCallbacks(callbacks));UiAutomation ui=test.getUiAutomation();AccessibilityNodeInfo root=null;for(int n=0;n<80;n++){Thread.sleep(100);root=ui.getRootInActiveWindow();if(root!=null&&ManufacturerFeatures.OEM.contentEquals(root.getPackageName()))break;if(root!=null)root.recycle();root=null;}if(root==null)throw new AssertionError("Original feature did not become visible");boolean sidebar=false;for(int attempt=0;attempt<35;attempt++){sidebar=ManufacturerFeatures.navigateSidebar(c,root);if(sidebar)break;root.recycle();Thread.sleep(100);root=ui.getRootInActiveWindow();if(root==null)throw new AssertionError("Native menu content unavailable");}out.putBoolean("oem_sidebar_selection_sent",sidebar);if(!sidebar)throw new AssertionError("Native menu selection unavailable");root.recycle();Thread.sleep(1200);root=ui.getRootInActiveWindow();if(root==null)throw new AssertionError("Native menu content unavailable");Set<String> ids=new LinkedHashSet<>();collect(root,ids,0,new int[]{0});out.putString("oem_visible_package",String.valueOf(root.getPackageName()));root.recycle();out.putString("oem_visible_view_ids",new JSONArray(ids).toString());out.putString("oem_route",id);boolean returned=false;String method="";for(int n=0;n<5;n++){int code=n<3?KeyEvent.KEYCODE_BACK:KeyEvent.KEYCODE_ESCAPE;long down=SystemClock.uptimeMillis();ui.injectInputEvent(new KeyEvent(down,down,KeyEvent.ACTION_DOWN,code,0,0,KeyCharacterMap.VIRTUAL_KEYBOARD,0,KeyEvent.FLAG_FROM_SYSTEM|KeyEvent.FLAG_VIRTUAL_HARD_KEY,InputDevice.SOURCE_KEYBOARD),true);ui.injectInputEvent(new KeyEvent(down,SystemClock.uptimeMillis(),KeyEvent.ACTION_UP,code,0,0,KeyCharacterMap.VIRTUAL_KEYBOARD,0,KeyEvent.FLAG_FROM_SYSTEM|KeyEvent.FLAG_VIRTUAL_HARD_KEY,InputDevice.SOURCE_KEYBOARD),true);method=code==KeyEvent.KEYCODE_BACK?"BACK":"EXIT";for(int wait=0;wait<35;wait++){Activity own=resumed.get();if(own!=null&&own.hasWindowFocus()){returned=true;break;}Thread.sleep(100);}if(returned)break;}if(!returned){root=ui.getRootInActiveWindow();if(root!=null)try{List<AccessibilityNodeInfo> back=root.findAccessibilityNodeInfosByViewId(ManufacturerFeatures.OEM+":id/iv_back_icon");for(AccessibilityNodeInfo b:back)try{if(b.isClickable())b.performAction(AccessibilityNodeInfo.ACTION_CLICK);}finally{b.recycle();}}finally{root.recycle();}for(int wait=0;wait<35;wait++){Activity own=resumed.get();if(own!=null&&own.hasWindowFocus()){returned=true;method="native_back_arrow";break;}Thread.sleep(100);}}out.putString("oem_return_method",method);test.runOnMainSync(()->app.unregisterActivityLifecycleCallbacks(callbacks));out.putBoolean("oem_back_returns_to_iraqhub",returned);if(!returned)throw new AssertionError("OEM Back did not return to IRAQhub");test.runOnMainSync(owner::finish);}
 private static void collect(AccessibilityNodeInfo node,Set<String> out,int depth,int[] count){if(node==null||depth>20||++count[0]>800)return;String id=node.getViewIdResourceName();if(id!=null&&id.startsWith(ManufacturerFeatures.OEM+":id/"))out.add(id.substring((ManufacturerFeatures.OEM+":id/").length()));for(int n=0;n<node.getChildCount();n++){AccessibilityNodeInfo child=node.getChild(n);if(child!=null)try{collect(child,out,depth+1,count);}finally{child.recycle();}}}
}